138	/// Keeps the selected entries plus every entry sharing a fixed or linked group
139	/// with a selection. Both release routes narrow `--package` through this.
140	fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
141	    workspace: &Workspace<'_, R, D>,
142	    entries: Vec<ReleaseDecisionEntry>,
143	    selected: &std::collections::BTreeSet<&ReleasePackageId>,
144	) -> Vec<ReleaseDecisionEntry> {
145	    // A plan-derived entry carries its linked group as a reason.
146	    let reason_groups = entries
147	        .iter()
148	        .filter(|entry| selected.contains(&entry.package))
149	        .flat_map(|entry| entry.reasons.iter())
150	        .filter_map(|reason| match reason {
151	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
152	            _ => None,
153	        })
154	        .collect::<std::collections::BTreeSet<_>>();
155	    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
156	    let config_groups = selected
157	        .iter()
158	        .flat_map(|selection| release_groups_of(workspace, selection))
159	        .collect::<std::collections::BTreeSet<_>>();
160	    entries
161	        .into_iter()
162	        .filter(|entry| {
163	            selected.contains(&entry.package)
164	                || entry.reasons.iter().any(|reason| {
165	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
166	                })
167	                || release_groups_of(workspace, &entry.package)
168	                    .iter()
169	                    .any(|group| config_groups.contains(group))
170	        })
171	        .collect()
172	}
